"""Build the public LX Help guides from reviewed, bilingual product copy."""
from pathlib import Path
from html import escape

# Each guide describes existing controls. Restricted tools stay restricted.
guides = {
 'portal': ('بوابة LXHAZZAA', 'LXHAZZAA portal', '/', [
  ('start','ابدأ من هنا','Getting started',
   '<p>اختر المنصة من بوابة LXHAZZAA: أطلس الرفات القديمة، أطلس الوثائق، مشجرة LXDNA Tree، أو LXDNA Control. تظهر الخدمة قيد التجهيز بعبارة «قريبًا»؛ ظهورها في البوابة لا يعني أن جميع أدواتها مفتوحة للجميع.</p><p>هذا مركز المساعدة لجميع المنصات. اختر اسم المنصة من قائمة الأدلة للوصول إلى شرحها، أو اضغط «مساعدة» في شريطها العلوي.</p>',
   '<p>Choose Ancient Remains Atlas, Documents Atlas, LXDNA Tree or LXDNA Control from the LXHAZZAA portal. “Coming soon” means a service is still in preparation; a portal card does not mean every tool is publicly available.</p><p>This is the shared help centre. Choose a guide from the navigation, or use Help in the relevant platform’s header.</p>'),
  ('account','الحساب والصلاحيات','Account and access',
   '<p>يمكن تصفح المحتوى العام دون حساب. استخدم «دخول / تسجيل» للخدمات المرتبطة بحسابك. تتوقف المساهمة والإدارة على الصلاحية المعتمدة؛ تسجيل الدخول وحده لا يمنح صلاحية إدارة المراجع أو مراجعة المواد.</p><p>إذا أعادتك أداة إلى صفحة «قريبًا»، تحقق من الدخول والصلاحية المطلوبة. لا ترسل كلمة المرور أو رمز الدخول إلى الدعم.</p>',
   '<p>Public content can be browsed without an account. Use Sign in / Register for account services. Contribution and administration require an approved role; signing in does not grant reference-management or review access.</p><p>If a restricted tool returns you to a coming-soon page, check your session and role. Never send a password or sign-in code to support.</p>'),
  ('appearance','اللغة والمظهر','Language and appearance',
   '<p>اختر العربية أو الإنجليزية من قائمة اللغة حيث تظهر، وبدّل الوضع النهاري أو المسائي من زر المظهر. في مركز المساعدة يمكنك تبديل لغة الدليل من الشريط العلوي.</p>',
   '<p>Use the language selector where available and the day/night control to change appearance. In LX Help, switch guide language using the header link.</p>'),
  ('privacy','الخصوصية والسياسات','Privacy and policies',
   '<p>اقرأ <a href="/policies/#terms">الشروط والأحكام</a> و<a href="/policies/#privacy">سياسة الخصوصية</a>. مشاركة البيانات مع منصة فحص لا تعني تلقائيًا الإذن بنشرها هنا. تختلف إتاحة السجل والملف الأصلي والبيانات الشخصية بحسب المنصة والصلاحية.</p>',
   '<p>Read the <a href="/policies/#terms">terms</a> and <a href="/policies/#privacy">privacy policy</a>. Sharing data with a testing service does not automatically authorise publication here. Record, original-file and personal-data access depend on the platform and permissions.</p>'),
  ('support','المساعدة والإبلاغ عن خطأ','Support and corrections',
   '<p>راسل <a href="mailto:lxhazzaa@gmail.com">lxhazzaa@gmail.com</a>، واذكر اسم المنصة ورقم السجل أو العينة والخطوات التي أدت للمشكلة. أرفق صورة بعد إخفاء البيانات الشخصية. لطلب تصحيح علمي أضف رابط الدراسة أو الدليل الأصلي وبيّن المعلومة المطلوب تصحيحها.</p><p>لا ترسل ملفًا جينيًا خاصًا أو وثيقة حساسة بالبريد دون الاتفاق على وسيلة مناسبة.</p>',
   '<p>Email <a href="mailto:lxhazzaa@gmail.com">lxhazzaa@gmail.com</a> with the platform, record or kit ID and steps to reproduce the issue. Redact personal details in screenshots. Scientific corrections should include the original study or evidence and the disputed field.</p><p>Do not email private genetic files or sensitive documents without arranging an appropriate method first.</p>')]),
 'atlas': ('أطلس الرفات القديمة','Ancient Remains Atlas','/lxhuman/atlas/',[
  ('search','البحث والفلاتر','Search and filters',
   '<ol><li>ابحث بمعرّف السجل أو العينة أو الموقع الأثري.</li><li>اختر Y-DNA للخط الأبوي أو mtDNA للخط الأمومي، ثم أدخل التحور. يشمل البحث الفروع المتحدرة عند حسم العلاقة في المرجع.</li><li>ضيّق النتائج بالدولة والجنس الجزيئي ونوع الموقع والتصنيف المكاني. استخدم «مسح الفلاتر» للبدء مجددًا.</li></ol><p>عدم وجود نتيجة لا يثبت عدم وجود العينة في الدراسات؛ قد لا يكون سجلها أو تصنيفها متاحًا في النسخة الحالية.</p>',
   '<ol><li>Search by record ID, sample ID or archaeological site.</li><li>Choose paternal Y-DNA or maternal mtDNA, then enter a branch. Descendants are included when the reference resolves their relationship.</li><li>Filter by country, genetic sex, location type and spatial classification. Clear filters to start again.</li></ol><p>No match does not prove a sample is absent from research; its record or assignment may be unavailable in this snapshot.</p>'),
  ('map','الخريطة ودقة الموضع','Map and location accuracy',
   '<p>النقطة ليست بالضرورة موضع القبر. اللون الأزرق للموقع الأثري، والذهبي للمدينة التقريبية، والأحمر الطيني لنقطة الدولة التقريبية. اقرأ «دقة الموقع» ومصدره قبل الاستنتاج.</p><p>لتحديد منطقة: حرّك الخريطة، واختر نصف القطر، ثم اضغط «تحديث النطاق». خيار «العينات ذات الإحداثيات فقط» يشمل الإحداثيات التقريبية أيضًا. قد تقل النقاط المعروضة لتحسين الأداء؛ البحث في السجل يشمل البيانات المتاحة.</p>',
   '<p>A point is not necessarily a grave coordinate. Blue denotes an archaeological site, gold an approximate city, and clay red an approximate country point. Read location accuracy and its source.</p><p>Move the map, select a radius and update the area. The coordinates-only option includes approximate points. The map may limit displayed points for performance; record search still covers the available data.</p>'),
  ('records','قراءة سجل الرفات','Reading a remains record',
   '<p>افتح العينة من نتائج البحث أو نقطة مفردة. راجع معرّف التحليل ومعرّف الفرد والتأريخ والموقع والدراسة؛ قد يكون للفرد أكثر من سجل تحليل، فلا تساوِ عدد السجلات بعدد الأشخاص تلقائيًا.</p><p>حقلا Y وmt مستقلان؛ قد يحمل الذكر نتيجة لكليهما. عدم توفر Y للأنثى أو لأي سجل لا يثبت سلالة. الجنس حسب المصدر وليس استنتاجًا من اسم التحور.</p><p>رابط المشجرة يفتح موضع التصنيف المتاح. عند عدم حسم الفرع التفصيلي يبقى الربط عند أصل مدعوم، ولا يُختلق فرع نهائي.</p>',
   '<p>Open a sample from results or a single map point. Review analysis ID, individual ID, dating, site and study. One person may have several analysis records; record totals are not automatically person totals.</p><p>Y and mt are independent fields. A male may have both. Missing Y for a female or any record is not a haplogroup assignment. Sex is taken from the source.</p><p>The tree link opens the available placement. Unresolved terminal calls stop at a supported ancestor rather than inventing a final branch.</p>'),
  ('dates','التأريخ والجودة والأعداد','Dating, quality and totals',
   '<p>BP يعني سنوات قبل 1950. مرشح «متوسط BP» يختبر المتوسط المبلّغ، وليس تداخل مجال التأريخ كله. تقييم Pass أو Provisional أو Questionable أو Critical من المصدر ولا يثبت صحة التحور.</p><p>عداد المواقع وقائمة «عدد العينات في كل موقع» يتبعان نتائج البحث. الموقع المسمّى يختلف عن عنقود نقاط على الخريطة.</p>',
   '<p>BP means years before 1950. The mean-BP filter uses the reported mean, not overlap with the entire dating interval. Source quality labels such as Pass or Questionable do not independently verify a haplogroup.</p><p>Site totals and samples-per-site follow the current search. A named archaeological site is different from a map-point cluster.</p>'),
  ('sources','المصادر وحدود الاستنتاج','Sources and interpretation',
   '<p>من المصادر الأكاديمية <a href="https://doi.org/10.7910/DVN/FFIDCW" target="_blank" rel="noopener noreferrer">AADR المنشور عبر Harvard Dataverse</a>. يرجع الحكم التفصيلي إلى الدراسة الأصلية المرتبطة بكل سجل وإصدار بياناتها.</p><p>التصنيفات الجينية لا تثبت وحدها قبيلة أو هوية إثنية حديثة أو هجرة الفرد. التصنيف المكاني غير المحسوم يبقى غير محسوم ما لم يوجد دليل منشور.</p>',
   '<p>Academic sources include <a href="https://doi.org/10.7910/DVN/FFIDCW" target="_blank" rel="noopener noreferrer">AADR on Harvard Dataverse</a>. Consult the original study and dataset version attached to each record.</p><p>A haplogroup alone does not establish a modern tribe, ethnicity or personal migration. Unresolved spatial classifications remain unresolved without published evidence.</p>')]),
 'tree': ('مشجرة LXDNA Tree','LXDNA Tree','/lxdnatree/',[
  ('search','اختيار المشجرة والبحث','Tree selection and search',
   '<p>اختر Y-DNA أو mtDNA أولًا، ثم ابحث باسم التحور أو العينة. هما مشجرتان مستقلتان؛ mtDNA يخص الخط الأمومي للذكور والإناث. تطبق الفلاتر على العرض والبيانات المرتبطة به.</p><p>العلاقات تتبع الأصل والفروع في المرجع، ولا تُستنتج من تشابه بداية اسم التحور أو من تكرار علامة واحدة.</p>',
   '<p>Choose Y-DNA or mtDNA before searching by branch or sample. These are separate trees; mtDNA traces the maternal line in both sexes. Filters apply to the relevant display and linked data.</p><p>Relationships follow reference ancestry, not label prefixes or a single recurring marker.</p>'),
  ('navigation','فتح الفروع وقراءة الرسم','Navigating branches',
   '<p>اضغط اسم التحور لتحديده، و+ أو − لفتح فروعه أو إغلاقها. يعرض قسم التحور المختار تشجيره والعينات المرتبطة به. استخدم رابط الأطلس لفتح رفات التحور.</p><p>النجمة * موضع قاعدي في المصدر، وليست تحورًا جديدًا. الاسم بين قوسين إحالة موثقة بين تسميات المصادر؛ لا يعني اختلاف ترتيب الفروع أنها مترادفة. ↥ يعني أصلًا مدعومًا مع بقاء الموضع التفصيلي غير محسوم.</p>',
   '<p>Select a branch by its name; use + or − to expand or collapse children. The selected-branch section displays its hierarchy and linked samples. Use its atlas link to explore associated remains.</p><p>An asterisk denotes a basal source position, not a new mutation. Parenthesised names are supported cross-source references, not proof that differently ordered branches are equivalent. ↥ marks a supported ancestor with unresolved terminal placement.</p>'),
  ('samples','الأيقونات والألوان والعينات','Sample icons and colours',
   '<p>الأيقونات تفرق بين عينات الرفات والأحياء والنتائج المتوقعة غير المؤكدة. رقم الرفات بني محمر، والمطوّرة أخضر، وغير المطوّرة أزرق، والتوقع غير المؤكد أحمر. حالة التأكيد بحسب المصدر، ولا تعني أن LX حلل ملف BAM.</p><p>استخدم «إخفاء العينات غير المؤكدة» أو «إخفاء عينات CSV» حيث يظهران. رقم العينة هو المعرّف المعروض؛ غياب العلم لا يبرر تخمين بلد. الأعداد داخل LX تخص سجلاته، وأي أعداد من مصدر خارجي تبقى منفصلة.</p>',
   '<p>Icons distinguish remains, living samples and unconfirmed predictions. Sample-number colours are reddish brown for remains, green for upgraded tests, blue for non-upgraded tests and red for unconfirmed predictions. Confirmation is source-reported; LX has not necessarily analysed BAM data.</p><p>Use the unconfirmed/CSV visibility controls where available. Kit numbers identify records; a missing flag is not a reason to infer a country. LX counts and external aggregate counts are separate.</p>'),
  ('ages','أعمار التحورات والمقارنة الأمومية','Branch ages and maternal comparison',
   '<p>عمر التكوّن وعمر السلف المشترك تقديران مختلفان حين يتيحهما المصدر. احتفظ بالمجال وعدم اليقين، ولا تحوّل تقدير الفرع إلى تاريخ فرد أو أصل جغرافي مؤكد.</p><p>في أداة الأصل المشترك لـmt أدخل من فرعين إلى 20 فرعًا مفصولة بفواصل أو أسطر. النتيجة علاقة شجرية؛ لا تثبت بلدًا أو إثنية أو زمن التقاء شخصين.</p>',
   '<p>Formation age and time to a common ancestor are different estimates when supplied by the source. Retain uncertainty; a branch-age estimate is not a person’s date or a proven geographical origin.</p><p>For mt common-ancestor comparison, enter 2–20 branches separated by commas or newlines. The result is a tree relationship, not proof of country, ethnicity or when two people last shared an ancestor.</p>'),
  ('sources','المصادر ومطابقة النتائج','Sources and matching',
   '<p>تعود بيانات YTree وMTree إلى <a href="https://www.yfull.com/tree/" target="_blank" rel="noopener noreferrer">YFull</a> و<a href="https://www.yfull.com/mtree/" target="_blank" rel="noopener noreferrer">مشجرته الأمومية</a>، بترخيص CC BY 4.0. أعادت LXHAZZAA تنسيقها وربطها بسجلات الأطلس. البيانات دون ضمان، ولا يعني استخدامها اعتماد YFull لمنصتنا.</p><p><a href="https://discover.familytreedna.com/" target="_blank" rel="noopener noreferrer">FamilyTreeDNA Discover</a> مصدر الشركة الأصلي لتصنيفاتها. YFull وFamilyTreeDNA جهتان تجاريتان متخصصتان؛ هذا ليس اعتمادًا جامعيًا أو حكوميًا لكل تصنيف.</p><p>FTDNA Stat تجميع مستقل غير رسمي. يوضح مربع «مطابقة المصادر» مقارنة الاسم ومسار الأسلاف والأصل المباشر بنسخة FamilyTreeDNA الرسمية بتاريخها. عدم اعتماد المطابقة لا يعني خطأ العينة؛ قد يكون المسار مختصرًا. اختلاف تاريخ النسخ قد يفسر فرق العدد، والعدد الناقص لا يُحوّل إلى صفر.</p><p>مراجعة R-V88 ذات الـ75 سجلًا قائمة محددة، وليست جميع عينات هذا الفرع. تفاصيل عدم اليقين تبقى مرتبطة بالسجل؛ المطابقة الاسمية ليست إعادة تحليل SNP.</p>',
   '<p>YTree and MTree are attributed to <a href="https://www.yfull.com/tree/" target="_blank" rel="noopener noreferrer">YFull</a> and its <a href="https://www.yfull.com/mtree/" target="_blank" rel="noopener noreferrer">maternal tree</a>, under CC BY 4.0. LXHAZZAA reformats and links these data to atlas records. Data are supplied without warranty; use does not imply YFull endorsement.</p><p><a href="https://discover.familytreedna.com/" target="_blank" rel="noopener noreferrer">FamilyTreeDNA Discover</a> is the company’s primary source. These specialist commercial sources are not university or government endorsements of every assignment.</p><p>FTDNA Stat is an independent, unofficial aggregation. The source-comparison panel checks exact names, ancestry and direct parents against a dated official FamilyTreeDNA snapshot. A held comparison may reflect a collapsed source path rather than an erroneous sample. Snapshot dates can explain count differences; missing counts are not zero.</p><p>The 75-record R-V88 review is a defined list, not all samples of the branch. Uncertainty remains attached to records; name matching is not SNP reanalysis.</p>'),
  ('license','التراخيص ونسب البيانات','Licensing and attribution',
   '<p>بيانات YFull منسوبة إلى YFullTeam (YTree وMTree). تشمل تعديلات LXHAZZAA تبسيط صيغة العرض والربط بالعينات وإحالات الأسماء؛ لا تدل على تعديل المصدر الأصلي أو اعتماده للمنصة. <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">شرح ترخيص CC BY 4.0</a>.</p>',
   '<p>YFull data are attributed to YFullTeam (YTree and MTree). LXHAZZAA modifications include display-format simplification, sample links and name cross-references. This does not imply changes to the original source or its endorsement. <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0 licence summary</a>.</p>')]),
 'control': ('LXDNA Control والمتنبئ','LXDNA Control and predictor','/lxdnacontrole/',[
  ('access','البدء والصلاحيات','Getting access',
   '<p>الواجهة العامة توضح الخدمات قيد التجهيز. أدوات «عيناتي» تحتاج حسابًا وصلاحية مفعّلة. إعداد مراجع المشاريع أداة إدارية منفصلة لا تظهر للجميع، ولا تمنحها صلاحية إدارة مشروع لدى شركة الفحص تلقائيًا.</p><p>قبل الحفظ أدخل رقم العينة وشركة الفحص والبلد، وأقر بالتفويض والمعالجة الخاصة. راجع <a href="/lxdnacontrole/terms/">شروط معالجة النتائج</a>. الاسم اختياري وخاص؛ حيازة السجل لا تثبت ملكية جينية.</p>',
   '<p>The public landing page identifies services in preparation. My Samples requires an account and enabled access. Project-reference management is a separate restricted tool; being a testing-company project administrator does not automatically grant LX administration.</p><p>Before saving, provide kit ID, testing provider and country and confirm authorisation for private processing. Read the <a href="/lxdnacontrole/terms/">processing terms</a>. Names are optional and private; record control is not proof of genetic ownership.</p>'),
  ('upload','تجهيز ملف الفرد أو نسخ صفه','Preparing an individual file or row',
   '<ol><li>من صفحة نتائج Y-STR في حساب شركة الفحص، استخدم التصدير المتاح لك أو اطلب ملفًا من مدير مشروعك. احتفظ بأسماء الماركرات وقيمها الأصلية؛ رابط صفحة النتائج وحده ليس ملف تحليل.</li><li>احفظ جدولًا واحدًا بصيغة CSV أو TSV. إذا كان الأصل Excel أو Google Sheets فصدّر الورقة المطلوبة إلى إحدى الصيغتين. لا ترفع PDF أو صورة أو صفحة HTML في مدخل STR.</li><li>ارفع الملف من «رفع ملف»، أو الصق عناوين الماركرات وصف عينتك معًا من «لصق النتائج». للجدول متعدد العينات أدخل رقم عينتك كما هو؛ يجب أن يطابق صفًا واحدًا بالضبط.</li><li>لا تحذف خانات ناقصة ولا تعِد ترتيب قيم بلا عناوين. راجع «العينة المقروءة» قبل التحليل، وأصلح الخطأ في الملف الأصلي عند رفضه.</li></ol><p>حد ملف STR الحالي 100KB. مثال تنسيق فقط: <code>DYS393=13</code> ثم <code>DYS390=24</code> في سطر آخر؛ المثال وحده لا يكفي لتنبؤ.</p>',
   '<ol><li>Use an export available in your testing account’s Y-STR results, or request a file from your project administrator. Preserve original marker names and values. A results-page URL is not an analysis file.</li><li>Save one table as CSV or TSV. Export the relevant worksheet from Excel or Google Sheets. Do not submit PDF, images or HTML to the STR input.</li><li>Upload a file or paste marker headers together with your row. For a multi-kit table, enter your exact kit ID; it must resolve to exactly one row.</li><li>Do not delete missing cells or reorder unnamed values. Review the parsed sample before analysis; correct rejected input in the original file.</li></ol><p>The STR file limit is 100KB. Format example only: <code>DYS393=13</code>, then <code>DYS390=24</code> on another line; this alone is insufficient for prediction.</p>'),
  ('panels','القيم بلا أسماء والمواضع الناقصة','Unnamed values and missing loci',
   '<p>الأفضل أسماء الماركرات مع قيمها. عند لصق أرقام فقط، اختر لوحة FTDNA الصحيحة 12 أو 25 أو 37 أو 67 أو 111، ثم اختر القيم متعددة النسخ مجمعة أو منفصلة بحسب الجدول الأصلي. لا تفترض أن ترتيب شركة أخرى يساوي ترتيب FTDNA.</p><p>لوحة 12 وحدها لا تحقق الحد الحالي من المواضع القابلة للمقارنة. القيم الناقصة ليست صفرًا. القيم الكسرية تُحفظ كما أُدخلت ويُبيّن استبعادها من نموذج المسافة الصحيحية؛ لا تُقرّب صامتًا.</p><p>إن وُجد تحور مؤكد سابقًا ضعه في الخيارات الإضافية فقط بعد تدقيقه؛ يقيّد نطاق المقارنة ولا يحوّل التوقع إلى تأكيد.</p>',
   '<p>Prefer named markers. For numbers-only input, select the correct FTDNA 12/25/37/67/111 panel and grouped or expanded multi-copy layout. Do not assume another provider uses FTDNA order.</p><p>Panel 12 alone does not meet the current comparable-locus minimum. Missing values are not zero. Microvariants are retained and reported as excluded from integer step-distance comparison, never silently rounded.</p><p>Only supply a previously confirmed SNP ancestor after checking it. It constrains comparison but does not confirm the predicted terminal branch.</p>'),
  ('projects','جداول المشاريع ومراجع المقارنة','Project tables and references',
   '<p>رفع مرجع المقارنة متاح للمخوّل إداريًا فقط. احصل أولًا على إذن استخدام البيانات؛ ظهور الجدول علنًا لا يكفي للسماح بإعادة نشر الأسماء أو الماركرات.</p><ol><li>جهّز CSV أو TSV برأس واحد وصف مستقل لكل عينة، يتضمن <code>kitId</code> و<code>haplogroup</code> و<code>snpVerified</code> وأسماء الماركرات.</li><li>في «إدارة مراجع المقارنة» أكمل اسم المصدر ورابطه وإصداره وتاريخه ثم اختر الملف. يمكن تنزيل قالب المرجع؛ لا يلزم كتابة JSON يدويًا.</li><li>ضع <code>snpVerified=true</code> فقط بعد تدقيق دليل تأكيد SNP. اسم التحور أو عبارة Big Y وحدها ليست تحققًا مستقلًا.</li><li>حلل العينة المطلوبة برقمها؛ استيراد المرجع هنا لا يحلل المشروع كله أو يحفظه وينشره تلقائيًا.</li></ol><p>المرجع ذو رقم مكرر متعارض يُستبعد من المقارنة. اختلاف أرقام الشخص نفسه بين المصادر لا يُحسم من تشابه الاسم وحده؛ يحتاج مراجعة الأدلة.</p>',
   '<p>Only authorised administrators can load comparison references. Obtain permission first; a public table does not automatically permit republishing names or markers.</p><ol><li>Prepare CSV/TSV with one header and one row per kit, including <code>kitId</code>, <code>haplogroup</code>, <code>snpVerified</code> and marker columns.</li><li>In reference management, enter source title, URL, version and date, then choose the file. A downloadable template avoids manual JSON editing.</li><li>Set <code>snpVerified=true</code> only after reviewing SNP-confirmation evidence. A branch label or “Big Y” text alone is not independent verification.</li><li>Analyse the selected kit by ID. Reference import does not automatically analyse, save or publish every project member.</li></ol><p>Conflicting duplicate IDs are excluded from comparison. Different IDs belonging to one person require evidence reconciliation, not name similarity alone.</p>'),
  ('method','منهج التنبؤ وحدود النتيجة','Prediction method and limitations',
   '<p>هذه طريقة مقارنة تجريبية داخل LX وليست منهجًا معتمدًا حكوميًا أو نسبة دقة مثبتة. تقارن STR بمراجع ذات تأكيد SNP، وتوحّد أسماء المواضع والنسخ المتعددة، وتعالج DYS389II كجزء مستقل عن DYS389I لتجنب العد المزدوج.</p><p>يُولد المسار من المشجرة المرجعية المختارة. تُستبعد المراجع المتعارضة أو غير المحسومة، والعينة نفسها عند تحديد رقمها. يعتمد الترشيح على أقرب المراجع ومواضعها المشتركة، ويتوقف عند ضعف التغطية أو تعارض الأدلة. يلزم 12 موضعًا قابلًا للمقارنة على الأقل؛ هذا حد حسابي لا ضمان للدقة.</p><p>تبقى أصوات المقارنة الأصلية محسوبة عند النزول للفروع حتى لا يتضخم الدعم بسبب سقوط المراجع المخالفة أو القصيرة. درجة الدعم ليست احتمال انتماء معايرًا؛ لا نستنتج منها قرابة أو قبيلة أو إثنية أو أبوة.</p><p>لا تُستبدل نتيجة SNP مؤكدة بتوقع STR. المطابقة والتوقع لا يعيدان تحليل التسلسل. يلزم اختبار مستقل بنتائج SNP مؤكدة قبل إعلان دقة علمية؛ الاختبارات البرمجية لا تقيس الدقة البيولوجية.</p>',
   '<p>This is an experimental LX comparison method, not a government-approved model or an established accuracy claim. It compares STR profiles with SNP-confirmed references, normalises locus names and multi-copy values, and treats DYS389II as the segment independent of DYS389I to avoid double counting.</p><p>Paths come from the selected reference tree. Conflicting or unresolved references are excluded, as is the target itself when its kit ID is supplied. Ranking uses nearest references and genuinely shared loci, stopping when coverage or evidence is insufficient. At least 12 comparable loci are required; that is a computational threshold, not an accuracy guarantee.</p><p>The original voting denominator is retained during descent so dissenting or shorter paths cannot artificially inflate support. Support is not a calibrated probability or evidence of kinship, tribe, ethnicity or paternity.</p><p>STR predictions do not override confirmed SNP results or reanalyse sequence data. Independent SNP-confirmed evaluation is required before a scientific accuracy claim; software tests do not measure biological accuracy.</p>'),
  ('reports','قراءة التقرير والحفظ','Reports and saving',
   '<p>المسافة الأقل تعني تشابهًا أكبر في المواضع المشتركة؛ لا تقارن مسافتين مع عدد مواضع مختلف وكأنهما متماثلتان. البدائل تلخص أقرب المراجع ولا تمثل كل الفروع أو نسبًا سكانية. افتح تفاصيل المقارنة لمراجعة المصدر والإصدار والاستبعادات.</p><p>«تنبّأ واحفظ» يحفظ النتيجة خاصة عند نجاح التحليل والرفع. انتظر رسالة النجاح؛ ظهور توقع وحده ليس إثبات حفظ. يمكنك تنزيل التقرير المتاح ومراجعة «عيناتي». النشر الآلي في المشجرة غير مفعّل.</p>',
   '<p>A smaller distance means greater similarity at shared loci. Distances based on different overlap are not directly equivalent. Alternatives summarise nearby references, not all branches or population frequencies. Expand the audit for sources, versions and exclusions.</p><p>Predict and save stores a private result only after analysis and upload succeed. Wait for confirmation; a prediction alone does not prove persistence. Download the available report and review My Samples. Automatic tree publication is not enabled.</p>'),
  ('files','RAW وملفات الدليل','RAW and evidence files',
   '<p>للأوتوسومال استخدم الملف النصي الأصلي بعد فك الضغط، بصيغة TXT أو CSV أو TSV، حتى 20MB، وبحقول rsid وchromosome وposition وgenotype. المتاح تقرير قراءة وجودة فقط؛ تحليل الأصول والصفات والصحة غير مفعّل، والأوتوسومال مستقل عن مشجرة Y وmt.</p><p>رفع الدليل يقبل الصيغ التي تظهر في الأداة ومنها BAM وVCF وPDF حتى 20MB. يُحفظ للمراجعة ولا يُحلل BAM أو VCF تلقائيًا ولا تتأكد النتيجة بمجرد الرفع. لا تغيّر امتداد ملف كبير لتجاوز الحد. رابط المصدر مرفق مرجعي وليس استيرادًا مباشرًا.</p>',
   '<p>For autosomal RAW, use the unzipped original TXT/CSV/TSV up to 20MB, with rsid, chromosome, position and genotype fields. Only parsing and quality reporting are available; ancestry, traits and health analysis are not enabled. Autosomal analysis is separate from Y/mt trees.</p><p>Evidence upload supports the formats listed in the tool, including BAM, VCF and PDF, up to 20MB. Files are stored for review; uploading does not automatically analyse sequence or verify an assignment. Do not rename a large file to bypass the limit. A source URL is a citation, not direct import.</p>'),
  ('privacy','الخصوصية والتصحيح والمساعدة','Privacy, corrections and help',
   '<p>الاسم والملف والتقرير خاصّة بحسب تفويض السجل وصلاحياته، والبريد مخفي افتراضيًا. لا تدخل الملفات تلقائيًا في التدريب. راجع شروط المعالجة للتفاصيل.</p><p>لطلب تغيير البلد أو الموقع والعلم، افتح العينة ثم اكتب القيمة المقترحة والسبب والدليل. التغيير يحتاج مراجعة مالك الموقع ويُسجل قراره؛ العلم مشتق من البلد المعتمد.</p><p>عند رفض الملف اقرأ رسالة الخطأ: طابق رقم العينة، ورؤوس الماركرات، وعدد النسخ، والحجم. إذا كانت المراجع غير كافية فقد تكون النتيجة «غير محسوم»؛ لا تُجبرها بتغيير التحور. للدعم استخدم <a href="/lxhelp/#support">التواصل مع LXHAZZAA</a>.</p>',
   '<p>Names, files and reports remain private according to record delegation and access controls. Email is hidden by default. Files are not automatically used for training. Consult processing terms for details.</p><p>Request country/location/flag corrections from the sample record with the proposed value, reason and evidence. The site owner reviews the request and the decision is logged; flags follow the accepted country.</p><p>For rejected files, check the message, kit ID, marker headers, copy counts and size. Insufficient references may legitimately produce an unresolved result; do not force a branch by changing input. Use <a href="/lxhelp/en/#support">LXHAZZAA support</a> for assistance.</p>'),
  ('sources','مصادر صيغ الإدخال','Input-format sources',
   '<p>تنسيق لوحات FTDNA يرجع إلى <a href="https://www.familytreedna.com/public/FTDNALearningCenter?iframe=ydna-results-overview" target="_blank" rel="noopener noreferrer">جدول الشركة التعليمي</a>. ومن المراجع الحكومية لأسماء Y-STR <a href="https://strbase-archive.nist.gov/ystr_fact.htm" target="_blank" rel="noopener noreferrer">NIST STRBase</a>. توثيق الصيغة لا يعني اعتماد هاتين الجهتين لمتنبئ LX أو إثبات دقته.</p>',
   '<p>FTDNA panel formatting follows the company’s <a href="https://www.familytreedna.com/public/FTDNALearningCenter?iframe=ydna-results-overview" target="_blank" rel="noopener noreferrer">learning-centre results table</a>. <a href="https://strbase-archive.nist.gov/ystr_fact.htm" target="_blank" rel="noopener noreferrer">NIST STRBase</a> is a government reference for Y-STR nomenclature. Format documentation is not endorsement or validation of the LX predictor.</p>')]),
 'documents': ('أطلس الوثائق','Documents Atlas','/lxdocumentary/',[
  ('access','حالة الإتاحة والمجموعات','Availability and collections',
   '<p>تظهر المنصة العامة حاليًا بعبارة «قريبًا». صفحات العمل والمساهمة للمخوّلين، ووجود هذا الدليل لا يفتح صلاحياتها أو يعني إطلاق الفهرس العام.</p><p>يشمل نطاق العمل الوثائق والسجلات والصكوك والرسائل والعقود، والمخطوطات والنقوش، والمراجع الداعمة لفهرستها. نتائج البحث عند الإتاحة تخص المواد المنشورة والمراجعة؛ لا تُعرض مادة خاصة لمجرد رفعها.</p>',
   '<p>The public landing page currently says Coming soon. Work and contribution pages require authorisation. This guide does not unlock access or announce a public catalogue launch.</p><p>The scope includes documents, records, deeds, letters, contracts, manuscripts, inscriptions and supporting references. When available, search covers published and reviewed materials, not private uploads by default.</p>'),
  ('contribute','تقديم مادة للمراجعة','Submitting a material',
   '<ol><li>أدخل نوع المادة وعنوانها ولغتها الأصلية ونظام كتابتها.</li><li>سجّل الجهة الحافظة ورقم الحفظ والمالك والمزوّد والباحث كلًا في دوره، مع رابط المصدر والاستشهاد.</li><li>حدد أساس الإتاحة ودليل الحق؛ عند غياب إذن الصورة اختر بيانات وصفية فقط دون رفع الأصل.</li><li>إذا كان الرفع مصرحًا، أرفق PDF أو JPG أو PNG حتى 15MB، ثم أقر بصحة التفويض وأرسل للمراجعة.</li></ol><p>الحفظ والإرسال لا يعنيان النشر. تابع حالة مساهمتك داخل حسابك إذا كانت الأداة مفعلة لك.</p>',
   '<ol><li>Enter material type, title, original language and writing system.</li><li>Record custodian, shelfmark, owner, provider and researcher in their respective roles, with source URL and citation.</li><li>State access rights and supporting evidence. Without image permission, choose metadata only and do not upload the original.</li><li>When authorised, attach PDF/JPG/PNG up to 15MB, confirm your declaration and submit for review.</li></ol><p>Saving and submitting do not mean publication. Follow contribution status in your account when the tool is enabled.</p>'),
  ('text','التفريغ والترجمة','Transcription and translation',
   '<p>يُسجل التفريغ باللغة الأصلية أولًا، ثم ترجمة ذلك التفريغ إلى اللغة المختارة. ميّز القراءة الجزئية والمسودة عن النص المراجع، وبيّن المواضع التالفة أو غير المقروءة بدل استكمالها كتأكيد.</p><p>لغة الواجهة لا تغيّر لغة المادة الأصلية. الترجمة مسودة ما لم تُراجع، ولا تثبت صورة الوثيقة وحدها صحة كل قراءة.</p>',
   '<p>Record the original-language transcription first, then its translation. Distinguish partial readings and drafts from reviewed text. Mark damaged or unreadable portions rather than presenting conjecture as fact.</p><p>Interface language does not change the source language. Translation remains a draft until reviewed; a document image alone does not verify every reading.</p>'),
  ('rights','الحقوق والعرض والتنزيل','Rights, display and download',
   '<p>حق وصف مادة لا يساوي حق نشر صورتها أو تنزيلها. الإتاحة تكون بيانات وصفية فقط، أو عرضًا دون تنزيل، أو عرضًا وتنزيلًا، بحسب التصريح والمراجعة. ذكر اسم المالك لا يغني عن الإذن.</p><p>عند فهرسة مادة من الأرشيف العثماني استخدم <a href="https://katalog.devletarsivleri.gov.tr/" target="_blank" rel="noopener noreferrer">الكتالوج الرسمي للأرشيفات الحكومية التركية</a> ورمز حفظها. هذه إحالة للمصدر وليست شراكة أو سحبًا آليًا للصور.</p>',
   '<p>Permission to describe a material is not permission to publish or download its image. Availability may be metadata only, view only, or view and download, subject to rights and review. Attribution alone does not replace permission.</p><p>For Ottoman archive entries, use the <a href="https://katalog.devletarsivleri.gov.tr/" target="_blank" rel="noopener noreferrer">official Turkish State Archives catalogue</a> and shelfmark. This is a source citation, not a partnership or automatic image import.</p>'),
  ('review','المراجعة والاعتراض والتصحيح','Review and corrections',
   '<p>يراجع المخوّل المصدر والحقوق ووصف المادة وحالة النص قبل الإتاحة. لطلب تصحيح أو اعتراض حقوقي، أرسل رقم السجل والمعلومة أو الحق محل الاعتراض والدليل إلى <a href="mailto:lxhazzaa@gmail.com">الدعم</a>. لا ترفق أصلًا سريًا في بلاغ عام.</p>',
   '<p>An authorised reviewer checks provenance, rights, description and text status before availability. For corrections or rights concerns, email <a href="mailto:lxhazzaa@gmail.com">support</a> with the record ID, disputed field or right and supporting evidence. Do not attach a confidential original to a public report.</p>')])}

# Shared actions are described separately from research interpretation.
guides['atlas'][3].insert(4, (
 'sharing', 'المشاركة والتصدير', 'Sharing and export',
 '<p>من زر مشاركة النتائج اختر نسخ رابط البحث، أو تنزيل البيانات ومصادرها بصيغة JSON، أو «تصدير PDF / طباعة». في نافذة الطباعة اختر الحفظ بصيغة PDF إن رغبت. يفتح الرابط الفلاتر نفسها؛ النتائج مرتبطة بإصدار البيانات وقد تتغير بعد التحديث.</p><p>التصدير العام محدود بما تسمح به صلاحية الحساب: حتى 20 سجلًا للزائر و100 للمستخدم المسجل. اقرأ عدد السجلات المصدّرة ولا تعتبر الملف جميع نتائج البحث تلقائيًا. إذا ظهر حد البحث المجاني فالدخول بحساب يتيح المتابعة بحسب الصلاحية.</p>',
 '<p>Use the results sharing control to copy the search URL, download records and sources as JSON, or export PDF / print. Select Save as PDF in the print dialog if desired. Shared links preserve filters; results depend on the data snapshot and can change after updates.</p><p>Public export limits follow account permissions: up to 20 records for visitors and 100 for signed-in users. Check the exported count; a download is not necessarily the complete result set. If the guest search limit appears, sign in to continue according to your permissions.</p>'))
guides['tree'][3].insert(4, (
 'sharing', 'مشاركة البحث وتصدير النتائج', 'Sharing and exporting results',
 '<p>اضغط «مشاركة» لنسخ رابط المشجرة والفلاتر الحالية. إذا تعذر النسخ يظهر الرابط لنسخه يدويًا. يفتح الرابط بحثًا في البيانات الموجودة ولا ينشر عينة جديدة.</p><p>«تصدير» ينزّل JSON يتضمن السجلات المسموح بها ومصادرها وإصدارها. حد الزائر 20 سجلًا والمسجل 100 بحسب الصلاحية؛ افصل بين العدد الكلي والعدد داخل الملف. التصدير ليس إعادة تحليل أو إثباتًا مستقلًا للنتيجة.</p>',
 '<p>Share copies the current tree and filter URL; if clipboard access fails, copy the displayed URL manually. Opening it searches existing data and does not publish a new sample.</p><p>Export downloads permitted records, sources and snapshot metadata as JSON. Visitor exports contain up to 20 records and signed-in exports up to 100, according to permissions. Distinguish total matches from exported records. An export is not reanalysis or independent confirmation.</p>'))

root = Path(__file__).resolve().parents[1]
base = root / 'public' / 'lxhelp'
def route(key, lang):
    return '/lxhelp/' + ('' if key == 'portal' else key + '/') + ('en/' if lang == 'en' else '')
for key,(ar,en,home,sections) in guides.items():
 for lang in ('ar','en'):
  eng=lang=='en'; title=en if eng else ar
  here=route(key,lang); other=route(key,'ar' if eng else 'en')
  label=lambda a,b:b if eng else a
  nav=''.join(f'<a href="{route(k,lang)}"'+(' aria-current="page"' if k==key else '')+f'>{escape(v[1] if eng else v[0])}</a>' for k,v in guides.items())
  toc=''.join(f'<a href="#{sid}">{escape(et if eng else at)}</a>' for sid,at,et,_,_ in sections)
  body=''.join(f'<section class="help-topic" id="{sid}"><h2>{escape(et if eng else at)}</h2>{eb if eng else ab}</section>' for sid,at,et,ab,eb in sections)
  if key=='tree':
   license=escape((root/'public/data/phylogeny/YFull-LICENSE.md').read_text())
   body+=f'<details class="help-license"><summary>{label("نص ترخيص البيانات الأصلي", "Original data licence text")}</summary><pre>{license}</pre></details>'
  html=f'''<!doctype html>
<html lang="{lang}" dir="{'ltr' if eng else 'rtl'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | LX Help</title><meta name="description" content="{label('دليل استخدام '+ar+' داخل مركز مساعدة LXHAZZAA','User guide for '+en+' in LXHAZZAA Help')}"><link rel="icon" type="image/svg+xml" href="/assets/favicon-lx.svg?v=1"><link rel="stylesheet" href="/assets/lxhelp.css?v=1"><script src="/assets/theme.js?v=1"></script><link rel="alternate" hreflang="ar" href="{route(key,'ar')}"><link rel="alternate" hreflang="en" href="{route(key,'en')}"></head>
<body><a class="help-skip" href="#content">{label('تجاوز إلى المحتوى','Skip to content')}</a><header class="help-header"><a class="help-brand" href="/" dir="ltr"><img src="/assets/LXHAZZAA_Separated_Assets_V3/lx-logo-gold-transparent.webp" width="58" height="58" alt="LXHAZZAA"><span>LXHAZZAA <i aria-hidden="true">|</i> <strong>LX Help</strong></span></a><nav aria-label="{label('روابط المساعدة','Help navigation')}"><a href="{home}">{label('العودة إلى المنصة','Back to platform')}</a><a href="{other}" lang="{'ar' if eng else 'en'}">{label('English','العربية')}</a><span data-lx-theme-slot></span></nav></header>
<div class="help-layout"><aside><nav class="help-guides" aria-label="{label('أدلة المنصات','Platform guides')}"><h2>{label('أدلة المنصات','Platform guides')}</h2>{nav}</nav></aside><main id="content"><p class="help-eyebrow">LXHAZZAA | LX HELP</p><h1>{label('مساعدة · ','Help · ')}{escape(title)}</h1><p class="help-intro">{label('شرح الاستخدام والمصادر وحدود النتائج، داخل LXHAZZAA.','Usage, sources and limitations, within LXHAZZAA.')}</p><nav class="help-toc" aria-label="{label('محتويات الدليل','On this page')}">{toc}</nav>{body}<p class="help-support">{label('لم تجد الإجابة؟','Need more help?')} <a href="{route('portal',lang)}#support">{label('تواصل معنا','Contact us')}</a></p></main></div><footer class="help-footer"><span>© LXHAZZAA · LX Help</span><a href="/policies/#terms">{label('الشروط والأحكام','Terms')}</a><a href="/policies/#privacy">{label('الخصوصية','Privacy')}</a></footer></body></html>'''
  dest=root/'public'/here.lstrip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html)
print('Built 10 static LX Help pages (Arabic / English).')
